function HUD.prototype.rectVerts(self, x, y, w, h)
    return {
        Vec2(x, y),
        Vec2(x + w, y),
        Vec2(x + w, y + h),
        Vec2(x, y + h)
    }
end
function HUD.prototype.screenVerts(self, w, h)
    return self:rectVerts(-w / 2, -h / 2, w, h)
end
function HUD.prototype.circle(self, draw, cx, cy, r, segs, width, color, from, sweep)
    do
        local i = 0
        while i < segs do
            local a0 = from + i / segs * sweep
            local a1 = from + (i + 1) / segs * sweep
            draw:drawSegment(
                Vec2(
                    cx + Math:cos(a0) * r,
                    cy + Math:sin(a0) * r
                ),
                Vec2(
                    cx + Math:cos(a1) * r,
                    cy + Math:sin(a1) * r
                ),
                width,
                col(color)
            )
            i = i + 1
        end
    end
end
function HUD.prototype.diamond(self, draw, x, y, s, fill, bw, border)
    draw:drawPolygon(
        {
            Vec2(x, y + s),
            Vec2(x + s, y),
            Vec2(x, y - s),
            Vec2(x - s, y)
        },
        col(fill),
        bw,
        col(border)
    )
end
function HUD.prototype.makeTitleFontLabel(self, parent, size, x, y)
