        local i = 0
        while i < #TITLE_FONTS do
            local lb = Label(TITLE_FONTS[i + 1], size)
            if lb ~= nil then
                lb.anchor = Vec2(0.5, 0.5)
                lb.position = Vec2(x, y)
                lb:addTo(parent)
                return lb
            end
            i = i + 1
        end
    end
    return makeLabel(
        parent,
        size - 4,
        x,
        y,
        0.5,
        0.5,
        Palette.paleInk
    )
end
