function HUD.prototype.updatePixelLife(self, st, x0, rowY)
    if self.heartTex == nil then
        return false
    end
    local bottomY = rowY - 24
    local step = st.maxLife > 5 and 36 or HEART_STEP
    local barX = x0 + Math:min(st.maxLife, HUD_MAX_HEARTS) * step + 16
    local ratio = st.maxLife > 0 and Math:max(
        0,
        Math:min(1, st.heroineLife / st.maxLife)
    ) or 0
    do
        local i = 0
        while i < #self.heartSps do
            local sp = self.heartSps[i + 1]
            local active = i < st.maxLife
            sp.visible = active
            if active then
                sp.position = Vec2(x0 + i * step, bottomY)
                sp.color = i < st.heroineLife and Color(255, 255, 255, 255) or Color(255, 255, 255, 70)
            end
            i = i + 1
        end
    end
    self.hud:drawPolygon(
        self:rectVerts(barX, bottomY, BAR_W, BAR_H),
        col(ink(Palette.paper.r, Palette.paper.g, Palette.paper.b, 245)),
        2,
        col(Palette.inkDark)
    )
    if ratio > 0 then
        local fw = (BAR_W - BAR_PAD * 2) * ratio
        self.hud:drawPolygon(
            self:rectVerts(barX + BAR_PAD, bottomY + BAR_PAD, fw, BAR_H - BAR_PAD * 2),
            col(Palette.vermilion)
        )
    end
    return true
end
