function HUD.prototype.onTitleTap(self, touch, w, h)
    if not self.titleMenuEnabled then
        return
    end
    local x = touch.location.x - w / 2
    local y = touch.location.y - h / 2
    local menuX = -w / 2 + MENU_X_OFF
    do
        local i = 0
        while i < #MENU_YS do
            local yy = -h / 2 + MENU_YS[i + 1]
            if Math:abs(x - menuX) <= MENU_HALF_X and Math:abs(y - yy) <= MENU_HALF_Y then
                if self.settingsOpen then
                    if i == 2 then
                        self:closeSettings()
                    end
                    return
                end
                if self.menuSel == i then
                    self:confirmCurrent()
                else
                    self.menuSel = i
                end
                return
            end
            i = i + 1
        end
    end
end
function HUD.prototype.confirmCurrent(self)
    if self.playLock then
        return
    end
    if self.menuSel == 0 then
        self.playLock = true
        self.menuFlashT = MENU_FLASH_T
        local cb = self.onPlayConfirmed
        if cb ~= nil then
            cb()
        end
    elseif self.menuSel == 1 then
        local gb = self.onGalleryConfirmed
        if gb ~= nil then
            gb()
        end
    else
        self:openSettings()
    end
end
function HUD.prototype.openSettings(self)
    self.settingsOpen = true
    self.settingsNode.visible = true
end
function HUD.prototype.closeSettings(self)
