function HUD.prototype.showEnding(self, id)
    local e = ENDINGS[id]
    if e == nil then
        return
    end
    local w = View.size.width
    local h = View.size.height
    self.endingBg:clear()
    self.endingBg:drawPolygon(
        self:screenVerts(w, h),
        col(ink(Palette.paper.r, Palette.paper.g, Palette.paper.b, 242))
    )
    self.endingBg:drawPolygon(
        self:rectVerts(-w / 2 + 14, -h / 2 + 14, w - 28, h - 28),
        col(NO_FILL),
        1,
        col(Palette.goldSoft)
    )
    setText(self.endingTitleLb, e.title)
    do
        local i = 0
        while i < #self.endingLineLbs do
            setText(self.endingLineLbs[i + 1], i < #e.lines and e.lines[i + 1] or "")
            i = i + 1
        end
    end
    local cands = ENDING_IMAGES[id]
    if cands ~= nil then
        local tex
        local used = ""
        for ____, p in ipairs(cands) do
            tex = Texture2D(p)
            if tex ~= nil then
                used = p
                break
            end
        end
        if tex ~= nil and used ~= "" then
            if self.endingSp == nil or self.endingTexId ~= used then
                local oldSp = self.endingSp
                if oldSp ~= nil then
                    oldSp:removeFromParent(true)
                end
                self.endingSp = nil
                local sp = Sprite(tex)
                if sp ~= nil then
                    sp:addTo(self.endingNode)
                    sp.position = Vec2(0, 0)
                    sp.anchor = Vec2(0.5, 0.5)
                    self.endingSp = sp
                    self.endingTexId = used
                end
            end
            if self.endingSp ~= nil then
                local iw = tex.width
                local ih = tex.height
                if iw > 0 and ih > 0 then
                    local s = Math:max(w / iw, h / ih)
                    self.endingSp.scaleX = s
                    self.endingSp.scaleY = s
                end
                self.endingSp.visible = true
            end
        else
            if self.endingSp ~= nil then
                self.endingSp.visible = false
            end
        end
    elseif self.endingSp ~= nil then
        self.endingSp.visible = false
    end
    self.endingTapGuard = 0.8
    self.endingNode.visible = true
end
function HUD.prototype.hideEnding(self)
