    local vh = View.size.height
    if pv.width > 0 and pv.height > 0 then
        local ps = Math:max(vw / pv.width, vh / pv.height)
        pv.anchor = Vec2(0.5, 0.5)
        pv.position = Vec2(0, 0)
        pv.scaleX = ps
        pv.scaleY = ps
    end
    pv.visible = true
    pv:addTo(self.prologueNode)
    self.prologueVideo = pv
    return pv
end
function HUD.prototype.playPrologue(self, onDone)
    local oldVid = self.prologueVideo
    if oldVid ~= nil then
        oldVid:removeFromParent()
        self.prologueVideo = nil
    end
    if self.prologuePlaying then
        return
    end
    self.prologuePlaying = true
    self.prologueStarted = false
    self.prologueWaitT = 0
    self.prologueDelayT = 0
    self.prologueTailT = 0
    if self.prologueCard ~= nil then
        self.prologueCard.visible = false
    end
    if self.prologueCardTitle ~= nil then
        self.prologueCardTitle.opacity = 0
    end
    if self.prologueCardSub ~= nil then
        self.prologueCardSub.opacity = 0
    end
    local oldTailVid = self.prologueCoverVideo
    if oldTailVid ~= nil then
        oldTailVid:removeFromParent()
        self.prologueCoverVideo = nil
    end
    self.prologueCoverFailed = false
    if self.prologueCardBg ~= nil then
        self.prologueCardBg.visible = true
    end
    self.prologueOnDone = onDone
    self.prologueNode.visible = true
    local coverVid = self.coverVideo
    if coverVid ~= nil then
        coverVid:pause()
    end
    self.prologueAudio = ""
    do
        local i = 0
        while i < #PROLOGUE_AUDIO_FILES do
            local f = PROLOGUE_AUDIO_FILES[i + 1]
            if Content:exist(f) then
                self.prologueAudio = f
                break
            end
            i = i + 1
        end
    end
    if self.prologueAudio ~= "" then
        stopBgm(0.15)
        do
            local function ____catch(e)
                local ____ = e
            end
            local ____try, ____hasReturned = pcall(function()
                Audio:playStream(self.prologueAudio, false, 0.15)
            end)
            if not ____try then
                ____catch(____hasReturned)
            end
        end
    end
    self.prologueNode:schedule(function(dt)
        if not self.prologuePlaying then
            return true
        end
        if self.prologueVideo == nil then
            self.prologueDelayT = self.prologueDelayT + dt
            if self.prologueDelayT < PROLOGUE_VIDEO_DELAY then
                return false
            end
            local pv = self:createPrologueVideo()
            if pv == nil then
                self:finishPrologue()
                return true
            end
            self.prologueWaitT = 0
            return false
        end
        local video = self.prologueVideo
        if not self.prologueStarted then
            if not video.paused then
                self.prologueStarted = true
            else
                self.prologueWaitT = self.prologueWaitT + dt
                if self.prologueWaitT > PROLOGUE_START_TIMEOUT then
                    self:finishPrologue()
                    return true
                end
            end
        elseif video.paused then
            self.prologueTailT = self.prologueTailT + dt
            local tailOn = self.prologueTailT > 0.05
            if self.prologueCard ~= nil then
                self.prologueCard.visible = tailOn
            end
            if tailOn and self.prologueCoverVideo == nil and not self.prologueCoverFailed and Content:exist(COVER_VIDEO_PIN) then
                local cv = VideoNode(COVER_VIDEO_PIN, true)
                if cv ~= nil then
                    local cw = cv.width
                    local ch = cv.height
                    local vw = View.size.width
                    local vh = View.size.height
                    if cw > 0 and ch > 0 then
                        local cs = Math:max(vw / cw, vh / ch)
                        cv.anchor = Vec2(0.5, 0.5)
                        cv.position = Vec2(0, 0)
                        cv.scaleX = cs
                        cv.scaleY = cs
                    end
                    cv.opacity = 0
                    cv:addTo(self.prologueNode)
                    self.prologueCoverVideo = cv
                else
                    self.prologueCoverFailed = true
                end
            end
            if self.prologueCardBg ~= nil then
                self.prologueCardBg.visible = self.prologueCoverVideo == nil
            end
            local cardU = Math:min(1, self.prologueTailT / 1.2)
            local cardA = Math:round(cardU * cardU * 255)
            if self.prologueCardTitle ~= nil then
                self.prologueCardTitle.opacity = cardA
            end
            if self.prologueCardSub ~= nil then
                self.prologueCardSub.opacity = cardA
            end
            if self.prologueCoverVideo ~= nil then
                self.prologueCoverVideo.opacity = cardU * cardU
            end
            if self.prologueTailT >= PROLOGUE_AUDIO_TAIL then
                self:finishPrologue()
                return true
            end
            return false
        else
            self.prologueTailT = 0
            if self.prologueCard ~= nil then
                self.prologueCard.visible = false
            end
        end
        return false
    end)
end
function HUD.prototype.finishPrologue(self)
    if not self.prologuePlaying then
        return
    end
    self.prologuePlaying = false
    local cb = self.prologueOnDone
    self.prologueOnDone = nil
    local video = self.prologueVideo
    if video ~= nil then
        video:pause()
    end
    local tailVid = self.prologueCoverVideo
    if tailVid ~= nil then
        tailVid:removeFromParent()
        self.prologueCoverVideo = nil
    end
    self.prologueNode.visible = false
    if self.prologueAudio ~= "" then
        self.prologueAudio = ""
        do
            local function ____catch(e)
                local ____ = e
            end
            local ____try, ____hasReturned = pcall(function()
                Audio:stopStream(0.4)
            end)
            if not ____try then
                ____catch(____hasReturned)
            end
        end
        playBgm("cover")
    end
    local coverVid = self.coverVideo
    if coverVid ~= nil and self.titleNode.visible then
        coverVid:resume()
    end
    if cb ~= nil then
        cb()
    end
end
function HUD.prototype.setPauseVisible(self, v)
    self.pauseNode.visible = v
end
function HUD.prototype.setMoonWheel(self, mode)
    self.wheelMode = mode
    local nSp = self.wheelNormalSp
    local aSp = self.wheelActiveSp
    local dSp = self.wheelDimSp
    if nSp ~= nil and aSp ~= nil and dSp ~= nil then
        nSp.visible = mode == "normal"
        aSp.visible = mode == "active"
        dSp.visible = mode == "dim"
    end
end
function HUD.prototype.handleTitleKey(self, key)
    if not self.titleMenuEnabled or self.prologuePlaying then
        return
    end
    if key == "Escape" then
        if self.settingsOpen then
            self:closeSettings()
        end
        return
    end
    if self.settingsOpen then
        return
    end
    local n = 3
    if key == "W" or key == "Up" then
        self.menuSel = (self.menuSel + n - 1) % n
    elseif key == "S" or key == "Down" then
        self.menuSel = (self.menuSel + 1) % n
    elseif key == "Return" or key == "Space" then
        self:confirmCurrent()
    end
end
function HUD.prototype.update(self, dt, args)
    local st = args.state
    local w = View.size.width
    local h = View.size.height
    local top = h / 2
    self.hud:clear()
    local baseX = -w / 2 + 44
    local rowY = top - 44
    local pxLife = self:updatePixelLife(st, baseX - 4, rowY)
    if not pxLife then
        do
            local i = 0
            while i < st.maxLife do
                local x = baseX + i * 30
                if i < st.heroineLife then
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        Palette.vermilion,
                        2,
                        Palette.inkDark
                    )
                else
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        NO_FILL,
                        2,
                        Palette.inkFaint
                    )
                end
                i = i + 1
            end
        end
    end
    local ix0 = pxLife and baseX - 4 + Math:min(st.maxLife, HUD_MAX_HEARTS) * (st.maxLife > 5 and 36 or HEART_STEP) + 16 + BAR_W + 16 or baseX + st.maxLife * 30 + 26
    do
        local i = 0
        while i < st.maxSwordIntent do
            local x = ix0 + i * 16
            if i < st.swordIntent then
                self.hud:drawSegment(
                    Vec2(x, rowY - 10),
                    Vec2(x, rowY + 10),
                    4,
                    col(Palette.moonCyan)
                )
            else
                self.hud:drawSegment(
                    Vec2(x, rowY - 10),
                    Vec2(x, rowY + 10),
                    2,
                    col(Palette.inkFaint)
                )
            end
            i = i + 1
        end
    end
    setText(self.phaseLb, st.phaseIndex >= 0 and st.phaseIndex < #PHASE_NAMES and PHASE_NAMES[st.phaseIndex + 1] or "")
    setText(
        self.loopLb,
        ("第" .. tostring(st.loopIndex + 1)) .. "周目"
    )
    local missionLb = self.guideMissionLb
    local stepLb = self.guideStepLb
    setText(
        missionLb,
        wrapCjk((("「" .. args.floorName) .. "」") .. args.mission, 13)
    )
    setText(
        stepLb,
        wrapCjk(args.objective, 14)
    )
    if missionLb ~= nil and stepLb ~= nil then
        local mh = missionLb.height
        stepLb.y = missionLb.y - (mh > 0 and mh or 30) - 8
    end
    local gw = args.guideLight == true
    if gw ~= self.guideWhite then
        self.guideWhite = gw
        local c = gw and Color(255, 255, 255, 255) or Color(0, 0, 0, 255)
        if self.guideTitleLb ~= nil then
            self.guideTitleLb.color = c
        end
        if missionLb ~= nil then
            missionLb.color = c
        end
        if stepLb ~= nil then
            stepLb.color = c
        end
    end
    setText(self.hintLb, args.hint)
    local boss = args.boss
    if boss ~= nil and not boss.dead and boss.maxHp > 0 then
        local bw = 520
        local bx = -bw / 2
        local by = -top + 66
        self.hud:drawPolygon(
            self:rectVerts(bx, by, bw, 12),
            col(NO_FILL),
            2,
            col(Palette.inkDark)
        )
        local frac = Math:max(
            0,
            Math:min(1, boss.hp / boss.maxHp)
        )
        if frac > 0 then
            self.hud:drawPolygon(
                self:rectVerts(bx + 2, by + 2, (bw - 4) * frac, 8),
                col(Palette.vermilion)
            )
        end
    end
    local wheelCx = w / 2 - 74
    local wheelCy = top - 40
    local nSp = self.wheelNormalSp
    local aSp = self.wheelActiveSp
    local dSp = self.wheelDimSp
    if nSp ~= nil and aSp ~= nil and dSp ~= nil then
        nSp.position = Vec2(wheelCx, wheelCy)
        aSp.position = Vec2(wheelCx, wheelCy)
        dSp.position = Vec2(wheelCx, wheelCy)
        nSp.visible = self.wheelMode == "normal"
        aSp.visible = self.wheelMode == "active"
        dSp.visible = self.wheelMode == "dim"
        self.wheelDraw:clear()
    else
        self.wheelDraw:clear()
        self:circle(
            self.wheelDraw,
            wheelCx,
            wheelCy,
            22,
            28,
            2,
            self.wheelMode == "active" and Palette.moonWhite or Palette.gold,
            0,
            Math.PI * 2
        )
    end
    self.flash:clear()
    if self.flashTimer > 0 then
        self.flashTimer = Math:max(0, self.flashTimer - dt)
        local a = Math:floor(255 * 0.35 * (self.flashTimer / FLASH_TIME))
        self.flash:drawPolygon(
            self:screenVerts(w, h),
            col(ink(Palette.vermilion.r, Palette.vermilion.g, Palette.vermilion.b, a))
        )
    end
    self.rewindDraw:clear()
    if self.rewindV >= 0 then
        local v = Math:max(
            0,
            Math:min(1, self.rewindV)
        )
        self.rewindDraw:drawPolygon(
            self:screenVerts(w, h),
            col(Palette.mist)
        )
        self:circle(
            self.rewindDraw,
            0,
            0,
            46,
            36,
            4,
            Palette.moonCyan,
            -Math.PI / 2,
            v * Math.PI * 2
        )
    end
    if args.fade ~= nil and args.fade > 0 then
        local f = Math:max(
            0,
            Math:min(1, args.fade)
        )
        self.hud:drawPolygon(
            self:screenVerts(w, h),
            col(ink(
                6,
                8,
                16,
                Math:floor(255 * f)
            ))
        )
    end
    if self.titleNode.visible then
        self:updateTitleEffects(dt, args.time, w, h)
    end
end
function HUD.prototype.updateTitleEffects(self, dt, time, w, h)
    if self.coverSp ~= nil then
        local breath = 1 + 0.015 * (1 + Math:sin(time * 0.7))
        self.coverSp.scaleX = self.coverBaseScale * breath
        self.coverSp.scaleY = self.coverBaseScale * breath
    end
    if self.titleNameLb ~= nil then
        local a = 205 + Math:floor(50 * Math:sin(time * 2.2))
        self.titleNameLb.color = Color(255, 233, 172, a)
    end
    self.menuFlashT = Math:max(0, self.menuFlashT - dt)
    self:drawMenu(time)
    self.particlesDraw:clear()
    do
        local i = 0
        while i < #self.particles do
            local p = self.particles[i + 1]
            p.y = p.y + p.vy * dt
            if p.y < -h / 2 - 12 then
                p.y = h / 2 + 12
                p.x = -w / 2 + 40 + Math:random() * (w - 80)
            end
            local tw = 0.55 + 0.45 * Math:sin(time * 2 + p.ph)
            local a = Math:floor(210 * tw)
            self.particlesDraw:drawDot(
                Vec2(p.x, p.y),
                p.r + 1.4 * tw,
                p.gold and Color(255, 216, 130, a) or Color(216, 230, 255, a)
            )
            i = i + 1
        end
    end
end
function HUD.prototype.drawMenu(self, time)
    local bi = 0
    do
        local i = 0
        while i < #self.menuDraws do
            local d = self.menuDraws[i + 1]
            local selected = i == self.menuSel and not self.settingsOpen
            d:clear()
            if self.menuBtnOk[i + 1] == true then
                local sp = self.menuBtns[bi + 1]
                bi = bi + 1
                if sp ~= nil then
                    local s = selected and 1.07 or 1
                    sp.scaleX = MENU_W / self.menuBtnW * s
                    sp.scaleY = MENU_H / self.menuBtnH * s
                    sp.opacity = selected and 1 or 0.72
                end
            elseif selected then
                d:drawPolygon(
                    self:rectVerts(-MENU_W / 2, -MENU_H / 2, MENU_W, MENU_H),
                    Color(96, 200, 255, 26),
                    2,
                    Color(96, 200, 255, 220)
                )
            end
            local lb = self.menuLbs[i + 1]
            if lb ~= nil then
                if selected then
                    local glow = 215 + Math:floor(40 * Math:sin(time * 3.4))
                    local flash = self.menuFlashT > 0
                    lb.color = flash and Color(255, 255, 255, 255) or Color(255, 255, 255, glow)
                    lb.scaleX = 1.06
                    lb.scaleY = 1.06
                else
                    lb.color = Color(255, 255, 255, 205)
                    lb.scaleX = 1
                    lb.scaleY = 1
                end
            end
            i = i + 1
        end
    end
end
return ____exports
